function exportarTablaExcel() {
    // Obtener el valor del campo "Fecha"
    const DateLastLog = document.getElementById('fechaFormList').value;
    const DateLastLogText = document.getElementById('fechaFormList').options[document.getElementById('fechaFormList').selectedIndex].text;

    // Validar si la fecha seleccionada es "--Seleccione Fecha--"
    if (DateLastLogText === "--Seleccione Fecha--") {
        alert("Por favor, seleccione una fecha antes de continuar.");
        return;  // Detener la ejecución de la función si la fecha no es válida
    }

    const CodMateria = document.getElementById('opcionesMateriaFormList');
    const NameMateria = CodMateria.options[CodMateria.selectedIndex].text;

    const PeriodoAcademico = document.getElementById('periodoFormList');
    const Periodo = PeriodoAcademico.options[PeriodoAcademico.selectedIndex].text;

    const NroSeccion = document.getElementById('opcionesSeccionFormList').value;
    const originalTable = document.getElementById('table');

    const NameCarrera = document.getElementById('EscuelaName').placeholder;

    const CodCarrera = document.getElementById('EscuelaName');
    const infoCod = CodCarrera.dataset.info;

    const InfoEscuela = CodCarrera.dataset.escuela;

    // Obtener el valor de la columna "Analista Encargado" (última columna)
    const analistaEncargadoCells = originalTable.querySelectorAll('tr td:last-child');
    const analistaEncargado = analistaEncargadoCells.length > 0 ? analistaEncargadoCells[0].textContent.trim() : 'No disponible';  // Toma el valor de la primera fila de la última columna

    // Crear un nuevo libro
    const wb = new ExcelJS.Workbook();

    // Crear la hoja de trabajo con el membrete y los datos fusionados
    const ws = wb.addWorksheet('Membrete y Datos');

    // 1. Membrete con datos adicionales
    let mergedData = [
        ["Universidad de Carabobo"],
        ["Facultad de Ciencias de la Salud"],
        ["Materia: " + NameMateria],
        ["Periodo Académico: " + Periodo],
        ["Sección: " + NroSeccion],
        ["Carrera: " + NameCarrera],
        ["Escuela: " + InfoEscuela],
        ["Fecha Ultima Actualizacion: " + DateLastLog],
        ["Analista Encargado: " + analistaEncargado], 
        [""],  // Espacio entre el membrete y la tabla de datos
        [""]
    ];

    // 2. Cabecera de la tabla con los datos: "Nro.", "Cédula de Identidad", "Apellido y Nombre", "Condición"
    const headerRow = ["Nro.", "Cédula de Identidad", "Apellido y Nombre", "Condición"];
    
    // Agregar la cabecera de la tabla al array de mergedData
    mergedData.push(headerRow);

    // 3. Obtener los datos de la tabla, eliminando las columnas "Fecha de última Actualización" y "Analista Encargado"
    const headers = originalTable.querySelectorAll('th');
    
    const columnToRemoveDate = Array.from(headers).findIndex(header => header.textContent.trim() === 'Fecha de última Actualización');
    const columnToRemoveAnalista = Array.from(headers).findIndex(header => header.textContent.trim() === 'Analista Encargado');

    const rows = originalTable.querySelectorAll('tr');
    
    rows.forEach((row, rowIndex) => {
        const rowData = [];
        const cells = row.querySelectorAll('td');
        
        // Si no es la primera fila (que contiene los encabezados), agrega la fila de datos
        if (rowIndex > 0) {
            // Agregar datos de la fila, excluyendo las columnas "Fecha de última Actualización" y "Analista Encargado"
            for (let i = 0; i < cells.length; i++) {
                if (i !== columnToRemoveDate && i !== columnToRemoveAnalista) {  // Excluir las columnas a eliminar
                    rowData.push(cells[i].textContent.trim());
                }
            }
            mergedData.push(rowData);
        }
    });

    // Estilo de borde engrosado solo para las celdas de la tabla
    const borderStyle = {
        top: { style: 'medium' },  // Engrosar el borde superior
        left: { style: 'medium' },  // Engrosar el borde izquierdo
        bottom: { style: 'medium' },  // Engrosar el borde inferior
        right: { style: 'medium' },  // Engrosar el borde derecho
    };

    // Agregar el membrete a las primeras filas sin bordes
    mergedData.forEach((row, index) => {
        const excelRow = ws.addRow(row);
        if (index >= 11) {  // Asegurarnos que no se añaden bordes al membrete
            excelRow.eachCell(cell => {
                cell.border = borderStyle;  // Agregar el borde engrosado a cada celda de la tabla
            });
        }
    });

    // Agregar la imagen al membrete
    const imagePath = 'data:image/png;base64,';  // Reemplaza con tu imagen base64

    const imageId = wb.addImage({
        base64: imagePath,
        extension: 'png',
    });

    ws.addImage(imageId, {
        tl: { col: 3, row: 1 },  // Coloca la imagen en la celda A1
        ext: { width: 200, height: 100 }
    });

    // Descargar el archivo final con la hoja fusionada
    wb.xlsx.writeBuffer().then((buffer) => {
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'Listado de Estudiantes.xlsx';
        link.click();
    });
}











function exportarTablaExcelACT() {
    // Obtener el valor del campo "Fecha"
    const DateLastLog = document.getElementById('fechaFormList').value;
    const DateLastLogText = document.getElementById('fechaFormList').options[document.getElementById('fechaFormList').selectedIndex].text;

    // Validar si la fecha seleccionada es "--Seleccione Fecha--"
    if (DateLastLogText === "--Seleccione Fecha--") {
        alert("Por favor, seleccione una fecha antes de continuar.");
        return;  // Detener la ejecución de la función si la fecha no es válida
    }

    const CodMateria = document.getElementById('opcionesMateriaFormList');
    const NameMateria = CodMateria.options[CodMateria.selectedIndex].text;

    const PeriodoAcademico = document.getElementById('periodoFormList');
    const Periodo = PeriodoAcademico.options[PeriodoAcademico.selectedIndex].text;

    const NroSeccion = document.getElementById('opcionesSeccionFormList').value;
    const originalTable = document.getElementById('table');

    const NameCarrera = document.getElementById('EscuelaName').placeholder;

    const CodCarrera = document.getElementById('EscuelaName');
    const infoCod = CodCarrera.dataset.info;

    const InfoEscuela = CodCarrera.dataset.escuela;

    // Solicitar nombre del docente y número de cédula
    const nombreDocente = prompt("Ingrese el nombre del docente (opcional):");
    const cedulaDocente = prompt("Ingrese el número de cédula del docente (opcional):");

    // Crear un nuevo libro
    const wb = new ExcelJS.Workbook();
    const ws = wb.addWorksheet('Datos'); // Una sola hoja

    // 1. Crear el membrete con datos adicionales
    const membrete = [
        ["Universidad de Carabobo"],
        ["Facultad de Ciencias de la Salud"],
        ["Asignatura: " + NameMateria],
        ["Periodo Académico: " + Periodo],
        ["Sección: " + NroSeccion],
        ["Carrera: " + NameCarrera],
        ["Escuela: " + InfoEscuela],
        ["Nombre del Docente: " + (nombreDocente ? nombreDocente : "N/A")],
        ["Nro. Cedula del Docente: " + (cedulaDocente ? cedulaDocente : "N/A")],
        [""]
    ];

    // Añadir el membrete a la hoja
    membrete.forEach((row, index) => {
        ws.addRow(row);
    });

    // 2. Agregar el título "ACTA DE EXAMEN"
    const tituloActa = [["", "", "", "", ""]];
    ws.addRow(tituloActa[0]);

    // 3. Filtrar y reorganizar la tabla, eliminando las columnas innecesarias
    const headers = originalTable.querySelectorAll('th');
    const columnIndexesToRemove = [];

    // Buscar las columnas que no necesitamos (Fecha de última Actualización y Analista Encargado)
    headers.forEach((header, index) => {
        if (header.textContent.trim() === 'Fecha de última Actualización' || header.textContent.trim() === 'Analista Encargado') {
            columnIndexesToRemove.push(index);
        }
    });

    // Filtrar las filas y reorganizar las columnas
    const rows = originalTable.querySelectorAll('tr');
    const filteredRows = [];

    // Nueva cabecera con el formato solicitado
    const newHeader = ["N°", "Cedula de Identidad", "Apellidos y Nombres", "Cond.", "Nota en N°", "Nota en letras"];

    // Agregar cabecera de la tabla con bordes negritos
    const headerRow = ws.addRow(newHeader);
    headerRow.eachCell((cell) => {
        cell.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FFFFFFFF' } // Fondo blanco
        };
        cell.border = {
            top: { style: 'medium', color: { argb: '000000' } }, // Borde superior negro
            left: { style: 'medium', color: { argb: '000000' } }, // Borde izquierdo negro
            bottom: { style: 'medium', color: { argb: '000000' } }, // Borde inferior negro
            right: { style: 'medium', color: { argb: '000000' } } // Borde derecho negro
        };
    });

    rows.forEach((row, rowIndex) => {
        const cells = row.querySelectorAll('td');
        const filteredCells = [];

        // Para las demás filas, reorganizar y eliminar las columnas innecesarias
        if (rowIndex > 0) {  // No procesar la primera fila (encabezado de la tabla)
            cells.forEach((cell, index) => {
                if (!columnIndexesToRemove.includes(index)) {
                    filteredCells.push(cell.innerText);
                }
            });

            // Asegurarse de agregar las columnas "Nota en N°" y "Nota en letras"
            filteredCells.push(""); // Columna "Nota en N°" vacía
            filteredCells.push(""); // Columna "Nota en letras" vacía

            filteredRows.push(filteredCells);
        }
    });

    // Añadir las filas de la tabla con fondo blanco y bordes negritos
    filteredRows.forEach(row => {
        const newRow = ws.addRow(row);
        newRow.eachCell((cell) => {
            // Establecer el fondo blanco para todas las celdas
            cell.fill = {
                type: 'pattern',
                pattern: 'solid',
                fgColor: { argb: 'FFFFFFFF' } // Fondo blanco
            };

            // Establecer los bordes negritos para todas las celdas
            cell.border = {
                top: { style: 'medium', color: { argb: '000000' } }, // Borde superior negro
                left: { style: 'medium', color: { argb: '000000' } }, // Borde izquierdo negro
                bottom: { style: 'medium', color: { argb: '000000' } }, // Borde inferior negro
                right: { style: 'medium', color: { argb: '000000' } } // Borde derecho negro
            };
        });
    });

    // 4. Agregar la imagen al membrete
    const imagePath = 'data:image/png;base64,';
    // Añadir la imagen al libro
    const imageId = wb.addImage({
        base64: imagePath,
        extension: 'png',
    });

    // Coloca la imagen en el membrete (ajusta el tamaño y posición de la imagen)
    ws.addImage(imageId, {
        tl: { col: 3, row: 1 },  // Coloca la imagen en la celda A1
        ext: { width: 200, height: 100 }  // Ajusta el tamaño
    });

    

    // Descargar el archivo final
    wb.xlsx.writeBuffer().then((buffer) => {
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'ACTA DE EXAMEN.xlsx';
        link.click();
    });
}
